from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union
from .parse_movement_line import parse_movement_line


def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    """
    List SKUs whose stock has not moved out for a long time (dead stock).
    """
    if idle_days < 1:
        raise ValueError("idle_days must be >= 1")

    on_hand_totals: Dict[str, int] = {}
    last_ship_day: Dict[str, int] = {}
    earliest_movement_day: Dict[str, int] = {}

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue

        parsed = parse_movement_line(stripped, case_sizes)
        day = parsed['day']
        sku = parsed['sku']
        mtype = parsed['type']
        qty = parsed['qty']

        if day > today:
            continue

        # Track earliest movement (for SKUs that never shipped)
        if sku not in earliest_movement_day or day < earliest_movement_day[sku]:
            earliest_movement_day[sku] = day

        # Track last shipment
        if mtype == 'SHP':
            if sku not in last_ship_day or day > last_ship_day[sku]:
                last_ship_day[sku] = day

        # Update on-hand stock
        on_hand_totals[sku] = on_hand_totals.get(sku, 0) + qty

    dead_skus = []
    for sku, total_qty in on_hand_totals.items():
        if total_qty > 0:
            # If never shipped, use earliest movement. Otherwise, use last shipment.
            last_activity = last_ship_day.get(sku, earliest_movement_day.get(sku))

            if last_activity is not None and (today - last_activity) >= idle_days:
                dead_skus.append(sku)

    return sorted(dead_skus)
"
    }
  },
  "messages": []
}
